use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Language {
    En,
    It,
    Fr,
    Es,
    Zh,
    /// Chinese, traditional script (Taiwan, Hong Kong).
    ZhTw,
    De,
    /// Portuguese as written in Brazil.
    PtBr,
    Ru,
    Uk,
    Ja,
    Ko,
    Tr,
    Pl,
    Nl,
    /// Friulian, a Romance language of north-east Italy.
    Fur,
}

impl Language {
    /// Every selectable UI language, in the order shown in the settings picker.
    pub const ALL: &'static [Language] = &[
        Language::En,
        Language::De,
        Language::Es,
        Language::Fr,
        Language::It,
        Language::Nl,
        Language::Pl,
        Language::PtBr,
        Language::Tr,
        Language::Ru,
        Language::Uk,
        Language::Ja,
        Language::Ko,
        Language::Zh,
        Language::ZhTw,
        Language::Fur,
    ];

    pub fn name(&self) -> &'static str {
        match self {
            Language::En => "English",
            Language::It => "Italiano",
            Language::Fr => "Français",
            Language::Es => "Español",
            Language::Zh => "中文 (简体)",
            Language::ZhTw => "中文 (繁體)",
            Language::De => "Deutsch",
            Language::PtBr => "Português (Brasil)",
            Language::Ru => "Русский",
            Language::Uk => "Українська",
            Language::Ja => "日本語",
            Language::Ko => "한국어",
            Language::Tr => "Türkçe",
            Language::Pl => "Polski",
            Language::Nl => "Nederlands",
            Language::Fur => "Furlan",
        }
    }

    pub fn code(&self) -> &'static str {
        match self {
            Language::En => "en",
            Language::It => "it",
            Language::Fr => "fr",
            Language::Es => "es",
            Language::Zh => "zh",
            Language::ZhTw => "zh-TW",
            Language::De => "de",
            Language::PtBr => "pt-BR",
            Language::Ru => "ru",
            Language::Uk => "uk",
            Language::Ja => "ja",
            Language::Ko => "ko",
            Language::Tr => "tr",
            Language::Pl => "pl",
            Language::Nl => "nl",
            Language::Fur => "fur",
        }
    }

    pub fn from_code(code: &str) -> Self {
        // Traditional Chinese is matched before the generic `zh` prefix, and Brazilian
        // Portuguese before European Portuguese, which falls back to English for now.
        let code = code.to_ascii_lowercase().replace('_', "-");
        let prefix = |p: &str| code == p || code.starts_with(&format!("{p}-"));
        if prefix("it") {
            Language::It
        } else if prefix("fr") {
            Language::Fr
        } else if prefix("es") {
            Language::Es
        } else if code.starts_with("zh-tw")
            || code.starts_with("zh-hk")
            || code.starts_with("zh-mo")
            || code.starts_with("zh-hant")
        {
            Language::ZhTw
        } else if prefix("zh") {
            Language::Zh
        } else if prefix("de") {
            Language::De
        } else if prefix("pt") {
            Language::PtBr
        } else if prefix("ru") {
            Language::Ru
        } else if prefix("uk") {
            Language::Uk
        } else if prefix("ja") {
            Language::Ja
        } else if prefix("ko") {
            Language::Ko
        } else if prefix("tr") {
            Language::Tr
        } else if prefix("pl") {
            Language::Pl
        } else if prefix("nl") {
            Language::Nl
        } else if prefix("fur") {
            Language::Fur
        } else {
            Language::En
        }
    }

    pub fn detect() -> Self {
        // The unit tests check English texts: they must not depend on the language of
        // the machine running them.
        if cfg!(test) {
            return Language::En;
        }
        // Check environment variables first
        for var in &["LC_ALL", "LC_MESSAGES", "LANG"] {
            if let Ok(val) = std::env::var(var) {
                // "it_IT.UTF-8" and friends: the codeset suffix is not part of the tag.
                let tag = val.split(['.', '@']).next().unwrap_or(&val);
                let detected = Language::from_code(tag);
                if detected != Language::En {
                    return detected;
                }
            }
        }

        #[cfg(windows)]
        {
            #[link(name = "kernel32")]
            extern "system" {
                fn GetUserDefaultUILanguage() -> u16;
            }
            let lang_id = unsafe { GetUserDefaultUILanguage() };
            let primary_lang = lang_id & 0x3ff;
            // Traditional Chinese carries the same primary id as simplified, so the
            // sub-language (the high bits) tells them apart: 0x0404 is zh-TW, 0x0c04
            // zh-HK, 0x1404 zh-MO.
            match primary_lang {
                0x10 => return Language::It,
                0x0c => return Language::Fr,
                0x0a => return Language::Es,
                0x04 => {
                    return match lang_id {
                        0x0404 | 0x0c04 | 0x1404 => Language::ZhTw,
                        _ => Language::Zh,
                    };
                }
                0x07 => return Language::De,
                0x16 => return Language::PtBr,
                0x19 => return Language::Ru,
                0x22 => return Language::Uk,
                0x11 => return Language::Ja,
                0x12 => return Language::Ko,
                0x1f => return Language::Tr,
                0x15 => return Language::Pl,
                0x13 => return Language::Nl,
                _ => {}
            }
        }

        Language::En
    }
}

